// H2: alerta si cambia el hash de pg_hba.conf o postgresql.conf respecto al guardado.
// Primera vez (sin hash guardado): no alerta; el otro camino del flujo guarda la referencia.
// La anti-repetición (mismo código y detalle en 10 min) la hace Enviar_Alerta.
const alertas = [];
for (const it of $input.all()) {
  const r = it.json;
  if (!r.hash_guardado || r.hash_guardado === r.hash_actual) continue;
  alertas.push({ json: {
    codigo: 'H2',
    severidad: 'CRÍTICA',
    tipo: 'Archivo de configuración de PostgreSQL modificado',
    tabla: r.archivo,
    detalle: `${r.archivo}: hash de referencia ${r.hash_guardado.slice(0, 8)}… ≠ hash actual ${r.hash_actual.slice(0, 8)}…`,
    query: `md5(pg_read_file('${r.archivo}'))`,
    usuario: 'N/A (cambio a nivel de archivo)',
    accion: 'Comparar el archivo con el respaldo, identificar quién lo cambió y restaurarlo. Si el cambio es legítimo, queda como nueva referencia.'
  }});
}
return alertas;

// Guarda el hash actual como referencia cuando es la primera vez o cuando cambió
// (se ejecuta después de enviar la alerta, así cada cambio alerta una sola vez).
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (r.hash_guardado === r.hash_actual) continue;
  // archivo y hash son fijos o hexadecimales: sin riesgo de inyección
  const archivo = String(r.archivo).replace(/[^A-Za-z0-9_.]/g, '');
  const hash = String(r.hash_actual).replace(/[^a-f0-9]/gi, '');
  out.push({ json: { sql_upsert:
    `INSERT INTO config_hashes (archivo, hash, actualizado) VALUES ('${archivo}', '${hash}', NOW()) ` +
    `ON CONFLICT (archivo) DO UPDATE SET hash = EXCLUDED.hash, actualizado = NOW();` } });
}
return out;
